CREATE TRIGGER `document_sections_frozen_update` BEFORE UPDATE ON `document_sections` WHEN ((SELECT frozen_at FROM documents WHERE id = OLD.document_id) IS NOT NULL OR (SELECT frozen_at FROM documents WHERE id = NEW.document_id) IS NOT NULL) AND NOT (OLD.redacted_at IS NULL AND NEW.redacted_at IS NOT NULL AND (SELECT redacted_at FROM documents WHERE id = OLD.document_id) IS NOT NULL AND NEW.`id` IS OLD.`id` AND NEW.`document_id` IS OLD.`document_id` AND NEW.`kind` IS OLD.`kind` AND NEW.`position` IS OLD.`position` AND NEW.`hidden` IS OLD.`hidden`) BEGIN SELECT RAISE(ABORT, 'document_sections of an issued document cannot change'); END;
