CREATE TRIGGER `document_lines_frozen_update` BEFORE UPDATE ON `document_lines` WHEN ((SELECT frozen_at FROM documents WHERE id = OLD.document_id) IS NOT NULL OR (SELECT frozen_at FROM documents WHERE id = NEW.document_id) IS NOT NULL) AND NOT (OLD.redacted_at IS NULL AND NEW.redacted_at IS NOT NULL AND (SELECT redacted_at FROM documents WHERE id = OLD.document_id) IS NOT NULL AND NEW.`id` IS OLD.`id` AND NEW.`document_id` IS OLD.`document_id` AND NEW.`position` IS OLD.`position` AND NEW.`catalogue_item_id` IS OLD.`catalogue_item_id` AND NEW.`sac` IS OLD.`sac` AND NEW.`qty_milli` IS OLD.`qty_milli` AND NEW.`unit` IS OLD.`unit` AND NEW.`rate_minor` IS OLD.`rate_minor` AND NEW.`discount_kind` IS OLD.`discount_kind` AND NEW.`discount_value` IS OLD.`discount_value` AND NEW.`taxable_minor` IS OLD.`taxable_minor` AND NEW.`gst_rate_bp` IS OLD.`gst_rate_bp` AND NEW.`cgst_minor` IS OLD.`cgst_minor` AND NEW.`sgst_minor` IS OLD.`sgst_minor` AND NEW.`igst_minor` IS OLD.`igst_minor` AND NEW.`line_total_minor` IS OLD.`line_total_minor` AND NEW.`catalogue_rate_minor` IS OLD.`catalogue_rate_minor` AND NEW.`catalogue_line` IS OLD.`catalogue_line`) BEGIN SELECT RAISE(ABORT, 'document_lines of an issued document cannot change'); END;
