CREATE TRIGGER `payment_schedules_frozen_update` BEFORE UPDATE ON `payment_schedules` WHEN ((SELECT frozen_at FROM documents WHERE id = OLD.document_id) IS NOT NULL OR (SELECT frozen_at FROM documents WHERE id = NEW.document_id) IS NOT NULL) AND NOT (OLD.redacted_at IS NULL AND NEW.redacted_at IS NOT NULL AND (SELECT redacted_at FROM documents WHERE id = OLD.document_id) IS NOT NULL AND NEW.`id` IS OLD.`id` AND NEW.`document_id` IS OLD.`document_id` AND NEW.`position` IS OLD.`position` AND NEW.`trigger` IS OLD.`trigger` AND NEW.`pct_bp` IS OLD.`pct_bp` AND NEW.`amount_minor` IS OLD.`amount_minor` AND NEW.`milestone_id` IS OLD.`milestone_id` AND NEW.`target_date` IS OLD.`target_date`) BEGIN SELECT RAISE(ABORT, 'payment_schedules of an issued document cannot change'); END;
